model Ball {
  x: Number
  y: Number
  vx: Number
  vy: Number
  radius: Number = 10
}

component BallSimulation {
  ref canvas
  state balls: Ball[] = []
  state paused = false
  state frameCount = 0
  state animationId: Number? = null

  fn init() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 8,
        radius: 10
      })
    }
    frameCount = 0
    paused = false
  }

  fn addBall() {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: 10
    })
  }

  fn togglePause() {
    paused = !paused
  }

  fn restart() {
    paused = false
    init()
  }

  fn updatePhysics() {
    const gravity = 0.2
    const width = 400
    const height = 300

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i]
      b.vy += gravity

      b.x += b.vx
      b.y += b.vy

      if (b.x - b.radius < 0) {
        b.x = b.radius
        b.vx = -b.vx
      }
      if (b.x + b.radius > width) {
        b.x = width - b.radius
        b.vx = -b.vx
      }
      if (b.y - b.radius < 0) {
        b.y = b.radius
        b.vy = -b.vy
      }
      if (b.y + b.radius > height) {
        b.y = height - b.radius
        b.vy = -b.vy
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const b1 = balls[i]
        const b2 = balls[j]
        const dx = b2.x - b1.x
        const dy = b2.y - b1.y
        const dist = Math.sqrt(dx * dx + dy * dy)
        const minDist = b1.radius + b2.radius

        if (dist < minDist) {
          const temp = b1.vx
          b1.vx = b2.vx
          b2.vx = temp
          const temp2 = b1.vy
          b1.vy = b2.vy
          b2.vy = temp2
        }
      }
    }
  }

  fn draw() {
    const ctx = canvas.getContext("2d")
    ctx.fillStyle = "#ffffff"
    ctx.fillRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn animate() {
    if (!paused) {
      updatePhysics()
      frameCount++
    }
    draw()
    animationId = requestAnimationFrame(animate)
  }

  mount {
    init()
    draw()
    animate()
    cleanup {
      if (animationId != null) {
        cancelAnimationFrame(animationId)
      }
    }
  }

  column gap=4 {
    row gap=2 {
      button "Agregar" primary -> addBall()
      button (paused ? "Reanudar" : "Pausar") primary -> togglePause()
      button "Reiniciar" primary -> restart()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frameCount}`
    }
    canvas ref=canvas width=400 height=300 style="border: 1px solid #ccc; display: block; background: white;"
  }
}

