model Ball {
  id: ID
  x: Number
  y: Number
  vx: Number
  vy: Number
  radius: Number = 10
}

component BallSimulator {
  state balls: Ball[] = []
  state frameCount = 0
  state isPaused = false
  ref canvas
  ref animationId = null

  fn initializeBalls {
    balls = []
    frameCount = 0
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 8,
        radius: 10
      })
    }
  }

  fn addBall {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: 10
    })
  }

  fn togglePause {
    isPaused = !isPaused
  }

  fn updatePhysics {
    const gravity = 0.2
    const width = 400
    const height = 300

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i]
      b.vy += gravity
      b.x += b.vx
      b.y += b.vy

      if (b.x - b.radius < 0) {
        b.x = b.radius
        b.vx = -b.vx
      }
      if (b.x + b.radius > width) {
        b.x = width - b.radius
        b.vx = -b.vx
      }
      if (b.y - b.radius < 0) {
        b.y = b.radius
        b.vy = -b.vy
      }
      if (b.y + b.radius > height) {
        b.y = height - b.radius
        b.vy = -b.vy
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const b1 = balls[i]
        const b2 = balls[j]
        const dx = b2.x - b1.x
        const dy = b2.y - b1.y
        const dist = Math.sqrt(dx * dx + dy * dy)
        const minDist = b1.radius + b2.radius

        if (dist < minDist) {
          const temp_vx = b1.vx
          const temp_vy = b1.vy
          b1.vx = b2.vx
          b1.vy = b2.vy
          b2.vx = temp_vx
          b2.vy = temp_vy
